-- PostgreSQL 18 explain.c show_sort_keys, show_agg_keys and the Values Scan
-- of a VALUES list are the reference, as is a derived table's plan under
-- its Subquery Scan.
CREATE TABLE t377 (a int, b int);
INSERT INTO t377 SELECT g % 10, g FROM generate_series(1, 100) g;
ANALYZE t377;
EXPLAIN (COSTS OFF) SELECT a + 1 AS q, b FROM t377 ORDER BY q DESC NULLS LAST, 2 NULLS FIRST, abs(b);
EXPLAIN (COSTS OFF) SELECT a, b, count(*) FROM t377 GROUP BY 2, a;
EXPLAIN (COSTS OFF) SELECT DISTINCT b, a FROM t377;
EXPLAIN (COSTS OFF) SELECT DISTINCT b FROM t377 ORDER BY b;
EXPLAIN (COSTS OFF, FORMAT JSON) SELECT a FROM t377 GROUP BY a ORDER BY a;
EXPLAIN (COSTS OFF) VALUES (1, 'a'), (2, 'b');
EXPLAIN (COSTS OFF, VERBOSE) VALUES (1, 'a'), (2, 'b');
EXPLAIN (COSTS OFF) VALUES (1, 'a');
EXPLAIN (COSTS OFF) SELECT * FROM (VALUES (1, 'a'), (2, 'b')) v;
EXPLAIN (COSTS OFF) VALUES (1), (2) ORDER BY 1;
EXPLAIN (COSTS OFF) VALUES (1), (2) UNION ALL VALUES (3), (4);
EXPLAIN (COSTS OFF) SELECT * FROM (VALUES (1), (2)) v(x) LIMIT 1;
EXPLAIN (COSTS OFF, FORMAT JSON) VALUES (1), (2);
SELECT * FROM (VALUES (1, 'a'), (2.5, NULL)) v;
VALUES (1, 'a'), (2.5, NULL);
EXPLAIN (COSTS OFF) SELECT s.a FROM (SELECT a, b FROM t377 ORDER BY b LIMIT 5) s;
